window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[351]={"id":"351","numero":351,"titre":"Agitation & délire aigu","objectifs":[{"id":"351-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’agitation","contenu":"<p>L'<span class=\"kw-def\">agitation</span> est une <strong><span class=\"kw-clinique\">activité motrice excessive</span>, improductive et stéréotypée</strong>, associée à un <strong><span class=\"kw-def\">état de tension intérieure</span></strong> (hyperactivité psychique). L'activité motrice n'est pas orientée vers un but.</p>\n      <p>Exemples sémiologiques : <span class=\"kw-clinique\">impossibilité de tenir en place</span>, marche de long en large, frottements de mains, fait de tirailler ses vêtements, incapacité de rester assis.</p>\n      <p><span class=\"kw-def\">Épidémiologie</span> : l'agitation représente <span class=\"kw-chiffre\">10 à 15 %</span> des consultations psychiatriques aux urgences. Le contexte de prise en charge est fréquemment <strong>sans consentement</strong>, sur demande de l'entourage ou des forces de l'ordre.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Aspécificité.</strong> L'agitation est <span class=\"kw-alerte\">totalement aspécifique</span> de tout trouble médical ou psychiatrique — elle n'oriente vers aucun diagnostic en soi et impose une démarche étiologique complète.\n      </div>\n      <p><strong>Diagnostics différentiels à distinguer :</strong></p>\n      <table >\n        <thead><tr><th>Entité</th><th>Distinction</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Hyperactivité physique</span></td><td>Motricité <strong>orientée vers un but</strong> (≠ improductive)</td></tr>\n          <tr><td><span class=\"kw-def\">Akathisie</span></td><td>Nécessité impérieuse de se déplacer ; mouvements incessants des jambes (souvent <span class=\"kw-etio\">iatrogène</span>, sous antipsychotiques)</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"351-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition des idées délirantes et hallucinations","contenu":"<p>Une <span class=\"kw-def\">idée délirante</span> est une <strong><span class=\"kw-def\">croyance erronée</span> fondée sur une <span class=\"kw-def\">déduction incorrecte</span> concernant la réalité</strong>, fermement soutenue <strong>en dépit de l'opinion générale et de toute preuve incontestable et évidente du contraire</strong>.</p>\n      <p>Une <span class=\"kw-def\">hallucination</span> est une <strong><span class=\"kw-def\">perception sans objet</span></strong>.</p>\n      <p>Ce sont <span class=\"kw-clinique\">les</span> deux <span class=\"kw-clinique\">symptômes psychotiques</span> de référence. Leur analyse sémiologique fine est détaillée dans l'objectif « syndrome délirant » (5 axes de caractérisation) et l'objectif « syndrome hallucinatoire ».</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 65 — Trouble délirant persistant</em></p>","frequence":0},{"id":"351-3","rang":"A","rubrique":"Définition","titre":"Connaître la définition du délire aigu","contenu":"<p>Le <span class=\"kw-def\">délire aigu</span> se définit par la présence d'une ou plusieurs <strong><span class=\"kw-clinique\">idées délirantes d'apparition récente</span></strong>, évoluant depuis <strong><span class=\"kw-chiffre\">moins d'un mois</span></strong>.</p>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> <span class=\"kw-def\">Agitation</span> et <span class=\"kw-def\">délire aigu</span> sont <strong>deux syndromes distincts</strong>, qui ne sont pas systématiquement associés. La démarche diagnostique et thérapeutique dépend de la présence d'un seul ou des deux syndromes.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 65 — Trouble délirant persistant</em></p>","frequence":0},{"id":"351-4","rang":"A","rubrique":"Etiologie","titre":"Connaître les étiologies de l’agitation selon l’âge incluant les causes toxiques","contenu":"<p>Une <strong><span class=\"kw-alerte\">cause non psychiatrique doit toujours être éliminée en priorité</span></strong>, quel que soit le <span class=\"kw-def\">terrain</span> et <span class=\"kw-clinique\">les</span> antécédents. Le panel étiologique se hiérarchise selon l'âge.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Sujet âgé</th><th>Adulte jeune</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Iatrogénie</span></td>\n            <td>\n              <strong>BZD :</strong> <span class=\"kw-ttt\">benzodiazépines</span> — <span class=\"kw-etio\">syndrome confusionnel</span> à l'instauration ou au <span class=\"kw-ttt\">sevrage</span>, <span class=\"kw-alerte\">effet paradoxal</span><br>\n              <strong>Antidépresseurs :</strong> <span class=\"kw-clinique\">confusion</span> ; syndrome sérotoninergique ; virage maniaque/hypomaniaque<br>\n              <strong>Autres :</strong> <span class=\"kw-ttt\">corticoïdes</span> ; <span class=\"kw-ttt\">agonistes dopaminergiques</span> ; <span class=\"kw-ttt\">anticholinergiques</span> ; plus rarement antipaludéens, <span class=\"kw-ttt\">isoniazide</span>, interféron\n            </td>\n            <td>\n              <strong>Fréquents :</strong> <span class=\"kw-ttt\">antidépresseurs</span> ; <span class=\"kw-ttt\">corticoïdes</span><br>\n              <strong>BZD :</strong> <span class=\"kw-alerte\">effet paradoxal</span> (agitation incoercible) — plus fréquent chez le jeune<br>\n              <strong>Antipaludéens :</strong> méfloquine ++\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Toxiques</span></td>\n            <td>\n              <strong>Intoxication :</strong> alcoolique aiguë ; au monoxyde de carbone<br>\n              <strong><span class=\"kw-ttt\">Sevrage</span> :</strong> alcoolique\n            </td>\n            <td>\n              <strong>Intoxication :</strong> <span class=\"kw-etio\">alcool</span> ; cannabis et LSD (hallucinogènes) ; <span class=\"kw-etio\">cocaïne, amphétamine, ecstasy</span> (psychostimulants) ; monoxyde de carbone<br>\n              <strong><span class=\"kw-ttt\">Sevrage</span> :</strong> <span class=\"kw-etio\">alcool</span> ; héroïne ; morphiniques\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Métabolique / endocrinien</span></td>\n            <td><span class=\"kw-bio\">dysnatrémie</span> ; <span class=\"kw-bio\">hypercalcémie</span> ; <span class=\"kw-etio\">hyperthyroïdie</span> ; <span class=\"kw-bio\">hypoglycémie</span></td>\n            <td><span class=\"kw-bio\">hypoglycémie</span> ; <span class=\"kw-etio\">hyperthyroïdie</span> ; <span class=\"kw-bio\">dysnatrémie</span> ; <span class=\"kw-bio\">hypercalcémie</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Neurologique</span></td>\n            <td><span class=\"kw-etio\">AVC</span> ; <span class=\"kw-clinique\">crise convulsive</span> ; HSD / HED ; tumeur ; démence débutante</td>\n            <td><span class=\"kw-clinique\">crise convulsive</span> ; <span class=\"kw-etio\">AVC</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Infectieux</span></td>\n            <td>infections (urinaire, pulmonaire…)</td>\n            <td><span class=\"kw-def\">méningo-<span class=\"kw-def\">encéphalite</span></span> herpétique ; <span class=\"kw-clinique\">neuropaludisme</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Autres</span></td>\n            <td>globe vésical ; fécalome ; pathologie cardiovasculaire (EP, <span class=\"kw-etio\">IDM</span>)</td>\n            <td>pathologie cardiovasculaire (EP)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Psychiatrique</span><br><em>(dg d'élimination)</em></td>\n            <td colspan=\"2\"><span class=\"kw-etio\">épisode dépressif caractérisé</span> avec agitation anxieuse ; épisode maniaque/hypomaniaque/mixte ; attaque de panique ; trouble délirant (jalousie, persécution)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 70 — Troubles psychiques du sujet agê · 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 77 — Addiction aux psychotropes</em></p>","frequence":2},{"id":"351-5","rang":"A","rubrique":"Etiologie","titre":"Connaître les étiologies des syndromes délirants aigus selon l’âge incluant les causes toxiques","contenu":"<p>La démarche est en <strong>deux temps</strong>.</p>\n      <p><strong>1 — Éliminer <span class=\"kw-clinique\">les</span> causes NON psychiatriques en priorité</strong> (même démarche étiologique que l'agitation) :</p>\n      <ul>\n        <li><strong>Sujet âgé :</strong> cause <span class=\"kw-etio\">iatrogène</span> ; <span class=\"kw-etio\">métabolique</span> ; <span class=\"kw-etio\">neurologique</span> ; <span class=\"kw-etio\">infectieuse</span> ; <span class=\"kw-etio\">toxique</span></li>\n        <li><strong>Adulte jeune :</strong> cause <span class=\"kw-etio\">iatrogène</span> ; <span class=\"kw-etio\">infectieuse</span> ; <span class=\"kw-etio\">métabolique</span> ; <span class=\"kw-etio\">endocrinienne</span></li>\n      </ul>\n      <p><strong>2 — Évoquer une étiologie psychiatrique en 2ᵉ intention</strong>, selon le tableau symptomatique :</p>\n      <table >\n        <thead><tr><th>Contexte</th><th>Entités à évoquer</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>Symptômes <span class=\"kw-clinique\">thymiques</span> associés</td>\n            <td>\n              <strong>Épisode maniaque ou mixte :</strong> thème mégalomaniaque ou de persécution ; accélération psychomotrice, logorrhée ; <span class=\"kw-clinique\">diminution du besoin de sommeil</span> — contexte de <span class=\"kw-etio\">trouble bipolaire</span> ou virage de l'humeur sous antidépresseur<br>\n              <strong><span class=\"kw-etio\">Épisode dépressif caractérisé</span> :</strong> thèmes de culpabilité, d'hypochondrie, de ruine ; <span class=\"kw-clinique\">ralentissement psychomoteur</span>\n            </td>\n          </tr>\n          <tr>\n            <td>Autres symptômes <span class=\"kw-clinique\">psychotiques</span></td>\n            <td>\n              <strong>Trouble psychotique bref :</strong> idées délirantes + hallucinations + désorganisation ; durée &gt;<span class=\"kw-chiffre\"> 1 jour</span> et &lt;<span class=\"kw-chiffre\"> 1 mois</span> — <span class=\"kw-alerte\">surdiagnostiqué, toujours évaluer la thymie</span><br>\n              <strong>Trouble psychotique chronique débutant ou non diagnostiqué :</strong> durée &lt;<span class=\"kw-chiffre\"> 6 mois</span> = trouble schizophréniforme ; &gt;<span class=\"kw-chiffre\"> 6 mois</span> = <span class=\"kw-etio\">schizophrénie</span> ou trouble schizoaffectif ; &gt;<span class=\"kw-chiffre\"> 1 mois</span> = trouble délirant<br>\n              <strong>Troubles psychotiques du post-partum</strong>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 65 — Trouble délirant persistant · 66 — Trouble dépressif · 69 — Trouble psy <span class=\"kw-ci\">grossesse</span> - postpartum</em></p>","frequence":0},{"id":"351-6","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer une agitation","contenu":"<p>Le diagnostic d'agitation est <strong>clinique</strong>, posé sur la définition : <span class=\"kw-clinique\">activité motrice excessive improductive</span> + <span class=\"kw-def\">état de tension intérieure</span>. L'<strong>interrogatoire de l'entourage</strong> est central (+++), le patient étant souvent peu coopérant.</p>\n      <p><strong>Éléments à recueillir à l'interrogatoire :</strong></p>\n      <ul>\n        <li>Date de début et mode évolutif : <span class=\"kw-clinique\">brutal</span> <span class=\"kw-bio\">vs</span> progressif ; permanent <span class=\"kw-bio\">vs</span> intermittent</li>\n        <li>Facteurs déclenchants</li>\n        <li>Prise de <span class=\"kw-etio\">toxiques</span></li>\n        <li><strong>Antécédents détaillés +++</strong> : recherche d'une <span class=\"kw-alerte\">décompensation</span> aiguë d'une pathologie sous-jacente</li>\n      </ul>\n      <p><strong>Diagnostics différentiels</strong> à écarter : <span class=\"kw-def\">hyperactivité physique</span> (motricité orientée vers un but) ; <span class=\"kw-def\">akathisie</span>.</p>","frequence":1},{"id":"351-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître l’analyse sémiologique d’un syndrome délirant","contenu":"<p>L'analyse sémiologique d'une <span class=\"kw-def\">idée délirante</span> repose sur <strong>5 axes de caractérisation</strong>, à décrire systématiquement.</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Caractérisation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1 · Thème</strong></td>\n            <td>Sujet principal du délire ; unique ou multiple ; un même thème peut se retrouver dans plusieurs troubles. Thème le plus fréquent : <span class=\"kw-clinique\">persécution</span> → toujours rechercher un <strong>persécuteur désigné</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>2 · Mécanisme</strong></td>\n            <td>Processus par lequel le délire s'établit :<br>\n              <strong>Interprétatif :</strong> interprétation délirante d'un fait réel<br>\n              <strong>Hallucinatoire :</strong> <span class=\"kw-def\">perception sans objet</span><br>\n              <strong>Intuitif :</strong> conviction délirante d'emblée, sans étayage<br>\n              <strong>Imaginatif :</strong> fabulation, invention</td>\n          </tr>\n          <tr>\n            <td><strong>3 · Systématisation</strong></td>\n            <td><strong>Systématisé / <span class=\"kw-def\">paranoïaque</span> :</strong> thème unique ; organisation interne logique<br>\n              <strong>Non systématisé / <span class=\"kw-def\">paranoïde</span> :</strong> thèmes multiples ; organisation interne incohérente, sans logique</td>\n          </tr>\n          <tr>\n            <td><strong>4 · Adhésion</strong></td>\n            <td>Degré de conviction attaché aux idées :<br>\n              <strong>Totale :</strong> adhésion inébranlable, inaccessible au raisonnement<br>\n              <strong>Partielle :</strong> auto-critique du délire par le patient</td>\n          </tr>\n          <tr>\n            <td><strong>5 · Retentissement +++</strong></td>\n            <td>Retentissement émotionnel et comportemental, à évaluer systématiquement : niveau d'<span class=\"kw-alerte\">anxiété</span> (souvent majeur) ; <span class=\"kw-alerte\">risque suicidaire</span> ; <span class=\"kw-alerte\">risque hétéro-agressif</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Symptômes psychiatriques associés à rechercher :</strong></p>\n      <ul>\n        <li>Autres <span class=\"kw-clinique\">symptômes psychotiques</span> : <span class=\"kw-clinique\">hallucinations</span> ; <span class=\"kw-def\">syndrome de désorganisation</span> (cognitif, émotionnel, comportemental) ; <span class=\"kw-def\">syndrome négatif</span></li>\n        <li>Symptômes <span class=\"kw-clinique\">thymiques</span> : déterminer leur chronologie par rapport aux <span class=\"kw-clinique\">symptômes psychotiques</span></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 65 — Trouble délirant persistant</em></p>","frequence":1},{"id":"351-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître l’analyse sémiologique d’un syndrome hallucinatoire","contenu":"<p>Une <span class=\"kw-def\">hallucination</span> est une <strong><span class=\"kw-def\">perception sans objet</span></strong>. Le mécanisme hallucinatoire est l'un des 4 mécanismes possibles d'une idée délirante ; la recherche d'<span class=\"kw-clinique\">hallucinations</span> fait partie du bilan des autres <span class=\"kw-clinique\">symptômes psychotiques</span> associés à un délire aigu. On distingue deux grands types.</p>\n      <p><strong>1 · Hallucinations <span class=\"kw-clinique\">psychosensorielles</span></strong> — <span class=\"kw-def\">perception sans objet</span> relevant d'une <strong>manifestation sensorielle</strong>, via l'un des 5 sens. Tous <span class=\"kw-clinique\">les</span> sens peuvent être touchés.</p>\n      <table >\n        <thead><tr><th>Modalité sensorielle</th><th>Caractéristiques sémiologiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Auditives ++</strong><br><em>(<span class=\"kw-clinique\">les</span> plus fréquentes)</em></td>\n            <td>Sons simples possibles (sonnerie, mélodie), mais surtout <span class=\"kw-clinique\">hallucinations acoustico-verbales (HAV)</span> : voix nettement localisées dans l'espace, conversant entre elles, s'adressant au sujet à la 3ᵉ personne, en phrases courtes à connotation négative.<br><strong>Signes évocateurs :</strong> <span class=\"kw-clinique\">attitudes d'écoute</span> ; moyens de protection (musique, se boucher <span class=\"kw-clinique\">les</span> oreilles) ; réponses brèves ou en aparté ; <span class=\"kw-clinique\">soliloquie</span> (parler tout seul) ; distractibilité pendant l'entretien — le sujet n'en parle pas toujours spontanément.</td>\n          </tr>\n          <tr>\n            <td><strong>Visuelles</strong></td>\n            <td>Élémentaires (lumières, taches colorées, phosphènes, ombres, flashs) ou complexes (objets, figures, scènes).</td>\n          </tr>\n          <tr>\n            <td><strong>Tactiles</strong></td>\n            <td>Coups de vent, brûlures, piqûres, sensation d'être couvert de parasites ; le sujet « touche » parfois ses hallucinations.</td>\n          </tr>\n          <tr>\n            <td><strong>Cénesthésiques</strong></td>\n            <td>Intéressent la sensibilité interne : impressions de transformation du corps (évidement, éclatement, possession).</td>\n          </tr>\n          <tr>\n            <td><strong>Olfactives / gustatives</strong><br><em>(moins fréquentes)</em></td>\n            <td>Olfactives : le plus souvent mauvaises odeurs émanant du patient lui-même. Gustatives : modification du goût des aliments.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>2 · Hallucinations <span class=\"kw-clinique\">intrapsychiques</span></strong> — <span class=\"kw-clinique\">phénomène psychique vécu dans la propre pensée du patient</span>, <strong>sans manifestation sensorielle</strong> (ni sensorialité, ni spatialité), perçu comme étranger au sujet. La pensée prend une forme hallucinatoire (voix intérieures, murmures <span class=\"kw-clinique\">intrapsychiques</span>). Elles traduisent une <span class=\"kw-clinique\">perte de l'intimité psychique</span> :</p>\n      <ul>\n        <li>Vol, divulgation, devinement, transmission de la pensée</li>\n        <li><strong>Pensées imposées</strong> ; sujet qui entend ses pensées comme si elles venaient d'autrui</li>\n        <li><strong>Écho de la pensée</strong> : le sujet entend ses propres pensées répétées à voix haute, comme renvoyées par un écho</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Une hallucination n'est pas forcément délirante ; quand une idée délirante en découle, on parle de <span class=\"kw-def\">mécanisme hallucinatoire</span>. <span class=\"kw-clinique\">Les</span> phénomènes <span class=\"kw-clinique\">intrapsychiques</span> (pensées imposées, écho et commentaire de la pensée) s'intègrent dans l'<span class=\"kw-def\">automatisme mental</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 61 — Trouble psychotique aigu · 63 — Trouble schizophrénique</em></p>","frequence":0},{"id":"351-9","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les éléments cliniques orientant vers une cause psychiatrique versus non psychiatrique","contenu":"<table >\n        <thead><tr><th>Élément</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Signes de gravité</span><br><em>(PEC somatique urgente)</em></td>\n            <td><span class=\"kw-etio\">syndrome confusionnel</span> ; <span class=\"kw-clinique\">déshydratation</span> sévère ; troubles hydro-électrolytiques ; <span class=\"kw-etio\">sepsis</span> ; <span class=\"kw-alerte\">défaillance</span> hémodynamique ; défaillance respiratoire</td>\n          </tr>\n          <tr>\n            <td>Orientent vers une cause <strong>NON psychiatrique</strong></td>\n            <td>\n              <strong>Neurologique ++ :</strong> <span class=\"kw-etio\">épilepsie</span> ; HSD ; hémorragie méningée ; tumeur ; <span class=\"kw-etio\">AVC</span> ; <span class=\"kw-etio\">AIT</span><br>\n              <strong>Métabolique :</strong> <span class=\"kw-bio\">hypoglycémie</span> ; troubles hydro-électrolytiques<br>\n              <strong>Endocrinien :</strong> dysthyroïdie ; hyperparathyroïdie ; hypercorticisme ; maladie d'Addison<br>\n              <strong><span class=\"kw-etio\">Infectieux</span> :</strong> <span class=\"kw-etio\">méningite</span> ; <span class=\"kw-def\">encéphalite</span> ; <span class=\"kw-clinique\">septicémie</span> ; <span class=\"kw-etio\">pneumonie</span>\n            </td>\n          </tr>\n          <tr>\n            <td>Orientent vers une cause <strong>psychiatrique</strong></td>\n            <td>\n              <strong>Thymiques :</strong> symptômes dépressifs ; symptômes maniaques<br>\n              <strong>Psychotiques :</strong> idées délirantes ; hallucinations<br>\n              <strong>Anxieux :</strong> symptômes anxieux\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Principe non négociable.</strong> Une cause <span class=\"kw-alerte\">non psychiatrique doit toujours être éliminée en premier</span>, quel que soit le <span class=\"kw-def\">terrain</span> et <span class=\"kw-clinique\">les</span> antécédents. Le diagnostic psychiatrique est un <strong>diagnostic d'élimination</strong>.\n      </div>","frequence":1},{"id":"351-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître les indications et la mise en œuvre des examens complémentaires dans un contexte d’agitation","contenu":"<table >\n        <thead><tr><th>Bilan minimal</th><th>En fonction du contexte</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <span class=\"kw-bio\">glycémie</span><br>\n              <span class=\"kw-bio\">ionogramme</span><br>\n              <span class=\"kw-bio\">calcémie</span><br>\n              <span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">CRP</span><br>\n              <span class=\"kw-bio\">bilan d'hémostase</span> — si traitement IM envisagé<br>\n              <span class=\"kw-bio\">ECG</span> — si traitement sédatif (antipsychotique) envisagé\n            </td>\n            <td>\n              <span class=\"kw-bio\">alcoolémie</span> ; <span class=\"kw-bio\">toxiques urinaires</span><br>\n              <span class=\"kw-bio\">bilan hépatique</span> ; <span class=\"kw-bio\">fonction rénale</span><br>\n              <span class=\"kw-bio\">TSH</span><br>\n              <span class=\"kw-imagerie\">TDM cérébral</span> ; <span class=\"kw-imagerie\">EEG</span><br>\n              <span class=\"kw-bio\">ponction lombaire</span> ; <span class=\"kw-bio\">ECBU</span><br>\n              <span class=\"kw-imagerie\">RXT</span> ; <span class=\"kw-bio\">frottis-goutte épaisse</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-bio\">ECG</span> avant tout antipsychotique sédatif.</strong> Recherche systématique d'un <span class=\"kw-alerte\">QT long</span> (risque de trouble du rythme).\n      </div>","frequence":3},{"id":"351-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge de l’épisode délirant aigu, de l’état d’agitation","contenu":"<p><strong>1 · Mesures générales</strong></p>\n      <ul>\n        <li>Le <strong>traitement étiologique</strong> prime (+++).</li>\n        <li><span class=\"kw-alerte\">Hospitalisation</span> en psychiatrie en <span class=\"kw-alerte\">urgence</span> : <strong>avec consentement</strong> par défaut ; <span class=\"kw-alerte\">refus + mise en danger → sans consentement</span>.</li>\n        <li>Prévention du <span class=\"kw-alerte\">risque suicidaire</span> (auto-agressif) ; évaluation du <span class=\"kw-alerte\">risque hétéro-agressif</span>.</li>\n        <li>Traitement pharmacologique en <strong>monothérapie</strong> ; privilégier la <strong>voie orale</strong> ; doses d'anxiolytiques <span class=\"kw-clinique\">les</span> plus faibles possible (surtout chez le sujet âgé) ; <span class=\"kw-alerte\">éviter l'escalade des doses</span> (effets cumulatifs différés sur la vigilance).</li>\n        <li><span class=\"kw-def\">Surveillance</span> rapprochée (tolérance, efficacité).</li>\n        <li>En cas de trouble psychiatrique associé : le traitement de fond est <strong>différé</strong> — après <span class=\"kw-def\">réévaluation</span> sémiologique à distance de l'<span class=\"kw-alerte\">urgence</span> et <span class=\"kw-ci\">bilan pré-thérapeutique</span>.</li>\n      </ul>\n      <p><strong>2 · Traitements pharmacologiques</strong> (à visée symptomatique : sédative et/ou anxiolytique)</p>\n      <table >\n        <thead><tr><th>Anxiolytiques</th><th>Antipsychotiques à visée sédative</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <strong>1ʳᵉ intention :</strong> <span class=\"kw-ttt\">benzodiazépine à demi-vie courte PO</span> (<span class=\"kw-ttt\">oxazépam</span>) ou autre anxiolytique (<span class=\"kw-ttt\">hydroxyzine</span>)<br>\n              <strong>Voie PO impossible :</strong> anxiolytique IM autre qu'une BZD (mauvaise biodisponibilité et durée d'action longue des BZD IM)<br>\n              <strong><span class=\"kw-ci\">CI : insuffisance respiratoire, myasthénie</span></strong>\n            </td>\n            <td>\n              <strong>Indication :</strong> <span class=\"kw-alerte\">état d'agitation très sévère</span> uniquement (risque d'aggravation des troubles de la vigilance)<br>\n              <strong><span class=\"kw-bio\">ECG</span> préalable :</strong> recherche d'un <span class=\"kw-alerte\">QT long</span> (cyamémazine IM non recommandée)<br>\n              <strong>PO :</strong> <span class=\"kw-ttt\">cyamémazine</span>, <span class=\"kw-ttt\">lévomépromazine</span>, <span class=\"kw-ttt\">loxapine</span><br>\n              <strong>En cas de refus :</strong> <span class=\"kw-ttt\">halopéridol</span> ou <span class=\"kw-ttt\">loxapine</span> IM<br>\n              <strong><span class=\"kw-ci\">CI absolues : glaucome aigu par fermeture de l'angle, adénome de prostate, QT long</span></strong>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>3 · Traitements non pharmacologiques</strong></p>\n      <ul>\n        <li><strong>PEC relationnelle</strong> en 1ʳᵉ intention : <span class=\"kw-def\">contact</span> verbal, climat de confiance, comportement empathique → désamorce une grande part des états d'agitation et prévient le passage à l'acte. C'est une <strong>obl<span class=\"kw-chiffre\">iga</span>tion médicale et médico-légale</strong> : la contention ne se justifie qu'après échec de la PEC relationnelle.</li>\n        <li><strong>Contention physique</strong> = pratique de <span class=\"kw-alerte\">dernier recours</span>, uniquement en cas de danger important et imminent. À durée limitée, le temps d'obtenir une sédation médicamenteuse efficace ; information claire et répétée + <span class=\"kw-def\">surveillance</span> rapprochée (constantes, vigilance).</li>\n        <li><strong>Autres mesures :</strong> environnement calme ; chambre éclairée ; retrait des objets dangereux ; fermeture des fenêtres.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong>Risques de la contention physique.</strong> Aggravation d'un <span class=\"kw-etio\">syndrome confusionnel</span> ; traumatisme psychologique ; fausse route et encombrement bronchique ; <span class=\"kw-clinique\">RGO</span>, <span class=\"kw-clinique\">constipation</span> voire occlusion ; <span class=\"kw-clinique\">rétention aiguë d'urine</span> ; escarres ; <span class=\"kw-clinique\">hypotension</span> orthostatique ; maladie thromboembolique.\n      </div>\n      <p><strong>4 · Spécificité du délire aigu</strong></p>\n      <ul>\n        <li>Orientation : <span class=\"kw-alerte\">hospitalisation</span> (soins libres ou sans consentement).</li>\n        <li>Prévention des risques auto- et hétéro-agressifs ; mesures générales (climat de confiance, alliance thérapeutique).</li>\n        <li>Traitement à visée sédative : <span class=\"kw-ttt\">BZD</span> ou <span class=\"kw-ttt\">antipsychotiques sédatifs</span> PO ; en cas de refus avec mise en danger → antipsychotique sédatif IM.</li>\n        <li>Éviter au maximum <span class=\"kw-clinique\">les</span> contentions.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 74 — Psychotropes</em></p>","frequence":10},{"id":"351-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les indications et les modalités de l’hospitalisation libre et sans consentement selon l’âge","contenu":"<p><strong><span class=\"kw-def\">Soins libres</span> (avec consentement)</strong> — modalité <strong>par défaut</strong> dès lors que le patient consent aux soins ; le <span class=\"kw-def\">consentement éclairé</span> reste le principe fondamental, le patient étant impliqué autant que possible dans le choix du traitement.</p>\n      <p><span class=\"kw-clinique\">Les</span> <strong>soins psychiatriques sans consentement (<span class=\"kw-def\">SPSC</span>)</strong> sont indiqués en cas de troubles rendant le consentement impossible et nécessitant des soins immédiats. On distingue 3 modalités :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">SPDT</span> — soins psychiatriques à la demande d'un tiers.</strong> Conditions : état mental nécessitant des soins immédiats + <span class=\"kw-def\">surveillance</span> constante, ET troubles rendant le consentement impossible. Procédure : demande manuscrite d'un <span class=\"kw-clinique\">tiers</span> (famille ou proche, hors soignants de l'établissement) + <strong>2 certificats médicaux</strong> circonstanciés de moins de <span class=\"kw-chiffre\">15 jours</span> ; admission prononcée par le <span class=\"kw-def\">directeur</span> de l'établissement.</li>\n        <li><strong><span class=\"kw-def\">SPDT en urgence</span>.</strong> En cas de <span class=\"kw-alerte\">risque grave d'atteinte à l'intégrité du malade</span> : admission au vu d'<strong>un seul certificat médical</strong> (pouvant émaner d'un médecin de l'établissement) ; demande du tiers identique.</li>\n        <li><strong><span class=\"kw-def\">SPPI</span> — soins en cas de péril imminent.</strong> Voie <strong>sans tiers</strong> : <span class=\"kw-alerte\">péril imminent</span> pour la santé du patient dûment constaté par <strong>un certificat médical</strong> ; admission par le <span class=\"kw-def\">directeur</span> de l'établissement.</li>\n        <li><strong><span class=\"kw-def\">SPDRE</span> — soins sur décision du représentant de l'État.</strong> Conditions : troubles nécessitant des soins ET <span class=\"kw-alerte\">compromettant la sûreté des personnes ou portant gravement atteinte à l'ordre public</span>. Procédure : <strong>arrêté du représentant de l'État (<span class=\"kw-def\">préfet</span>)</strong> + certificat médical (hors médecin de l'établissement d'accueil).</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>« Selon l'âge » — à compléter.</strong> <span class=\"kw-clinique\">Les</span> sources de l'item 351 et la section correspondante du Collège ne détaillent pas de modalités spécifiques au <span class=\"kw-clinique\">mineur</span> (place de l'autorité parentale) ni au sujet âgé. Contenu rattaché à l'item 15.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 15 — Soins psychiatriques sans consentement · 70 — Troubles psychiques du sujet agê</em></p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Prise en charge :</strong> réalisée au minimum <span class=\"kw-alerte\">aux urgences</span><br><strong>Priorité absolue :</strong> <span class=\"kw-etio\">éliminer une cause non psychiatrique</span> en 1er lieu, dans tous <span class=\"kw-clinique\">les</span> cas quel que soit le <span class=\"kw-def\">terrain</span><br><strong>1er geste :</strong> <span class=\"kw-ttt\">contact verbal</span> instaurant un climat de confiance, qui désamorce un nombre important d'états d'agitation et peut prévenir un <span class=\"kw-alerte\">passage à l'acte</span></p>","hospit":"<p><strong>Urgences :</strong> évaluation initiale et <span class=\"kw-bio\">bilan paraclinique</span> systématiques<br><strong><span class=\"kw-alerte\">Hospitalisation</span> en psychiatrie :</strong> si <span class=\"kw-etio\">trouble psychiatrique sous-jacent</span> nécessitant des soins<br><strong>Délire aigu :</strong> <span class=\"kw-ttt\">hospitalisation</span> systématique, en <span class=\"kw-ttt\">soins libres</span> ou <span class=\"kw-ttt\">sans consentement</span> selon l'âge et l'adhésion</p>","redflags":"<ul><li><span class=\"kw-alerte\">Syndrome confusionnel</span></li><li><span class=\"kw-clinique\">Déshydratation sévère</span>, <span class=\"kw-bio\">troubles hydro-électrolytiques</span></li><li>Signes de <span class=\"kw-alerte\">sepsis</span>, <span class=\"kw-alerte\">choc cardiovasculaire</span>, <span class=\"kw-alerte\">détresse respiratoire aiguë</span></li><li>Risque de <span class=\"kw-alerte\">passage à l'acte auto ou hétéro-agressif</span></li></ul>","principes":"<p>En <span class=\"kw-alerte\">urgence</span>, le traitement <span class=\"kw-etio\">médicamenteux</span> est <span class=\"kw-ttt\">exclusivement symptomatique</span> (sédatif et/ou anxiolytique) ; le traitement du trouble de fond se met en place de manière <span class=\"kw-ttt\">différée</span>.</p><p><strong>Mesures non pharmacologiques (1re intention)</strong></p><ul><li><span class=\"kw-ttt\">Environnement calme</span>, chambre éclairée</li><li>Prévention du <span class=\"kw-alerte\">passage à l'acte</span> : retirer <span class=\"kw-clinique\">les</span> objets dangereux, fermer les fenêtres</li><li><span class=\"kw-ttt\">PEC relationnelle</span> empathique = obl<span class=\"kw-chiffre\">iga</span>tion médicale et médico-légale, préalable obligatoire à toute contention</li></ul><p><strong>Contention mécanique (dernier recours)</strong></p><p>Sédation médicamenteuse systématiquement prescrite en cas de contention physique</p><ul><li><span class=\"kw-ttt\">Pratique de dernier recours</span>, uniquement après échec de la PEC relationnelle</li><li>Indiquée seulement si <span class=\"kw-alerte\">danger important et imminent</span> pour le patient ou autrui</li><li><span class=\"kw-ttt\">Surveillance régulière</span> (constantes, vigilance), durée limitée au temps d'obtenir une sédation efficace</li></ul><p><strong>Traitement pharmacologique symptomatique</strong></p><p>Objectif : apaiser rapidement le patient sans le sédater de façon excessive</p><ul><li>Privilégier la <span class=\"kw-ttt\">monothérapie</span> et la voie <span class=\"kw-ttt\">orale</span> (plutôt qu'IM)</li><li><span class=\"kw-clinique\">Agitation + anxiété intenses</span> : <span class=\"kw-ttt\">BZD à demi-vie courte</span> (ex. <span class=\"kw-ttt\">oxazépam</span> per os)</li><li><span class=\"kw-clinique\">Agitation sévère</span> : <span class=\"kw-ttt\">antipsychotiques sédatifs</span> (<span class=\"kw-ttt\">cyamémazine</span>, <span class=\"kw-ttt\">loxapine</span>), avec <span class=\"kw-ci\">ECG préalable</span> (allongement du QT)</li><li>Doses <span class=\"kw-chiffre\">les plus faibles possibles</span> surtout chez la personne âgée, éviter l'escalade des doses</li></ul><p><strong>Selon l'étiologie</strong></p><ul><li>Cause <span class=\"kw-etio\">non psychiatrique</span> : PEC en <span class=\"kw-alerte\">urgence</span> de l'étiologie sous-jacente</li><li>Étiologie indéterminée : application des mêmes principes pharmacologiques symptomatiques</li><li><span class=\"kw-etio\">Trouble psychiatrique</span> : traitement symptomatique en <span class=\"kw-alerte\">urgence</span>, traitement de fond <span class=\"kw-ttt\">différé</span> (après évaluation à distance et <span class=\"kw-ci\">bilan pré-thérapeutique</span>)</li></ul>","suivi":"<p><strong>Sous contention / sédation :</strong> <span class=\"kw-ttt\">surveillance régulière</span> des <span class=\"kw-clinique\">constantes</span> et de la <span class=\"kw-clinique\">vigilance</span><br><strong>Risque :</strong> effets cumulatifs différés sur la vigilance (<span class=\"kw-alerte\">fausse route</span>, <span class=\"kw-alerte\">complications de décubitus</span>)<br><strong>À distance de l'<span class=\"kw-alerte\">urgence</span> :</strong> évaluation sémiologique correcte et <span class=\"kw-ci\">bilan pré-thérapeutique</span> avant tout traitement de fond</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Patient agité et/ou délire aigu aux urgences","detail":"<h4>CAT — Agitation et délire aigu — Démarche diagnostique et thérapeutique en <span class=\"kw-alerte\">urgence</span></h4>","branches":[{"to":"q-gravite","label":"Évaluation initiale","color":"blue"}]},{"id":"q-gravite","kind":"decision","label":"Signes de gravité organiques ? — Confusion, sepsis/choc, détresse respiratoire, déshydratation sévère","branches":[{"to":"t-rea","label":"Oui (signe de gravité)","color":"red"},{"to":"q-cause","label":"Non","color":"green"}]},{"id":"t-rea","kind":"terminal","label":"Urgence vitale — PEC réanimatoire","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Syndrome confusionnel</span>, <span class=\"kw-alerte\">sepsis</span> ou <span class=\"kw-alerte\">choc cardiovasculaire</span></li><li><span class=\"kw-alerte\">Détresse respiratoire aiguë</span>, <span class=\"kw-clinique\">déshydratation sévère</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">PEC réanimatoire</span> immédiate + traitement de l'<span class=\"kw-etio\">étiologie organique</span></li></ul>"},{"id":"q-cause","kind":"decision","label":"Cause non psychiatrique au bilan ? — Bilan minimal : <span class=\"kw-bio\">NFS, CRP, ionogramme, glycémie, calcémie</span>","branches":[{"to":"t-etio","label":"Cause organique / toxique / iatrogène","color":"amber"},{"to":"q-sev","label":"Bilan négatif → origine psychiatrique","color":"blue"}]},{"id":"t-etio","kind":"terminal","label":"PEC en urgence de l'étiologie sous-jacente","color":"amber","detail":"<h4>Conduite</h4><ul><li>Traitement de la cause <span class=\"kw-etio\">organique</span>, <span class=\"kw-etio\">toxique</span> ou <span class=\"kw-etio\">iatrogène</span> identifiée</li></ul><h4>Paraclinique</h4><ul><li>Selon contexte : <span class=\"kw-bio\">TSH</span>, <span class=\"kw-bio\">alcoolémie</span>, <span class=\"kw-bio\">toxiques urinaires</span>, <span class=\"kw-imagerie\">imagerie cérébrale</span>, <span class=\"kw-imagerie\">EEG</span></li></ul>"},{"id":"q-sev","kind":"decision","label":"Origine psychiatrique : quelle intensité ? — Choix de la sédation symptomatique selon l'intensité de l'agitation","branches":[{"to":"t-bzd","label":"Agitation + anxiété intenses","color":"amber"},{"to":"t-aps","label":"Agitation sévère","color":"amber"}]},{"id":"t-bzd","kind":"terminal","label":"BZD à demi-vie courte + orientation psychiatrique","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">BZD à demi-vie courte</span> (ex. <span class=\"kw-ttt\">oxazépam</span> per os)</li><li><span class=\"kw-ttt\">Monothérapie</span>, dose <span class=\"kw-chiffre\">la plus faible possible</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Hospitalisation en psychiatrie</span> si <span class=\"kw-etio\">trouble</span> nécessitant des soins (<span class=\"kw-ttt\">soins libres</span> ou <span class=\"kw-ttt\">sans consentement</span>)</li></ul>"},{"id":"t-aps","kind":"terminal","label":"Antipsychotique sédatif (agitation sévère)","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antipsychotique sédatif</span> per os (<span class=\"kw-ttt\">cyamémazine</span>, <span class=\"kw-ttt\">loxapine</span>), réservé aux <span class=\"kw-clinique\">agitations sévères</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-ci\">ECG préalable</span> obl<span class=\"kw-chiffre\">iga</span>toire (risque d'<span class=\"kw-alerte\">allongement du QT</span>)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Contention mécanique</span> de dernier recours si <span class=\"kw-alerte\">danger imminent</span>, avec <span class=\"kw-ttt\">sédation systématique</span> et <span class=\"kw-def\">surveillance</span></li></ul>"}]},"cards":[{"i":"5509cae743e2","n":351,"o":"351-1","u":"Définition","t":"Connaître la définition de l’agitation","q":"Quels exemples sémiologiques sont caractéristiques de l'agitation ?","a":"<ul><li>Impossibilité de tenir en place</li><li>Marche de long en large</li><li>Frottements de mains</li><li>Tirailler ses vêtements</li><li>Incapacité de rester assis</li></ul>"},{"i":"718091473463","n":351,"o":"351-1","u":"Définition","t":"Connaître la définition de l’agitation","q":"Quelle est la définition clinique de l'agitation dans le contexte médical ?","a":"<p>L'agitation se définit comme une <strong>activité motrice excessive, improductive et stéréotypée</strong>, associée à un état de <strong>tension intérieure (hyperactivité psychique)</strong>. L'activité motrice n'est pas orientée vers un but précis.</p>"},{"i":"a442620149a9","n":351,"o":"351-1","u":"Définition","t":"Connaître la définition de l’agitation","q":"Comment différencier l'agitation d'une simple hyperactivité physique ?","a":"<p>Contrairement à l'agitation, l'hyperactivité physique se caractérise par une <strong>motricité orientée vers un but</strong>, n'étant donc pas improductive.</p>"},{"i":"cb898d047cec","n":351,"o":"351-1","u":"Définition","t":"Connaître la définition de l’agitation","q":"Quelle est la valeur diagnostique de l'agitation en médecine d'urgence ?","a":"<p>L'agitation est un signe totalement <strong>aspécifique</strong>. Elle n'oriente vers aucun diagnostic particulier, qu'il soit médical ou psychiatrique. Elle impose une <strong>démarche étiologique complète</strong>.</p>"},{"i":"e3d05f354e41","n":351,"o":"351-1","u":"Définition","t":"Connaître la définition de l’agitation","q":"Comment distinguer l'agitation de l'akathisie ?","a":"<p>L'akathisie est caractérisée par une <strong>nécessité impérieuse de se déplacer</strong> et des <strong>mouvements incessants des jambes</strong>, souvent d'origine <strong>iatrogène</strong> (notamment sous antipsychotiques), ce qui la différencie de l'agitation qui est une activité motrice non orientée vers un but.</p>"},{"i":"2cd3e431ae67","n":351,"o":"351-10","u":"Prise en charge","t":"Connaître les indications et la mise en œuvre des examens complémentaires dans un contexte d’agitation","q":"Dans quel contexte clinique réalise-t-on un bilan minimal face à une agitation aiguë ?","a":"<p>Le bilan minimal face à une agitation aiguë est réalisé en fonction du <strong>contexte clinique</strong> du patient.</p>"},{"i":"31ec9175c031","n":351,"o":"351-10","u":"Prise en charge","t":"Connaître les indications et la mise en œuvre des examens complémentaires dans un contexte d’agitation","q":"Quels sont les examens biologiques essentiels à considérer dans le bilan minimal devant une agitation aiguë ?","a":"<ul><li><strong>Glycémie</strong></li><li><strong>Ionogramme sanguin</strong></li><li><strong>Calcémie</strong></li><li><strong>Numération Formule Sanguine (NFS)</strong></li><li><strong>Protéine C réactive (CRP)</strong></li></ul>"},{"i":"5ffa2eb81d6c","n":351,"o":"351-10","u":"Prise en charge","t":"Connaître les indications et la mise en œuvre des examens complémentaires dans un contexte d’agitation","q":"Quand devrait-on envisager une TSH, un RXT ou un frottis-goutte épaisse dans le bilan étiologique d'une agitation aiguë ?","a":"<ul><li><strong>TSH</strong> : si une pathologie thyroïdienne (hyperthyroïdie notamment) est suspectée.</li><li><strong>Radiographie thoracique (RXT)</strong> : si une pathologie pulmonaire (ex: pneumopathie) ou cardiaque est suspectée.</li><li><strong>Frottis-goutte épaisse</strong> : si le contexte épidémiologique ou clinique évoque un paludisme.</li></ul>"},{"i":"b273c0ac61de","n":351,"o":"351-10","u":"Prise en charge","t":"Connaître les indications et la mise en œuvre des examens complémentaires dans un contexte d’agitation","q":"Dans quelles situations spécifiques doit-on inclure un bilan d'hémostase, une alcoolémie, des toxiques urinaires, un bilan hépatique ou une fonction rénale devant une agitation aiguë ?","a":"<ul><li><strong>Bilan d'hémostase</strong> : si un <strong>traitement intramusculaire (IM)</strong> est envisagé.</li><li><strong>Alcoolémie</strong> et <strong>toxiques urinaires</strong> : systématiquement recherchés pour identifier une éventuelle intoxication.</li><li><strong>Bilan hépatique</strong> et <strong>fonction rénale</strong> : pour évaluer l'état général et d'éventuelles contre-indications médicamenteuses ou pour orienter vers une étiologie métabolique.</li></ul>"},{"i":"baf60d88daae","n":351,"o":"351-10","u":"Prise en charge","t":"Connaître les indications et la mise en œuvre des examens complémentaires dans un contexte d’agitation","q":"Quels examens neurologiques et infectieux majeurs peuvent être envisagés lors d'un bilan complémentaire devant une agitation aiguë ?","a":"<ul><li><strong>TDM cérébral</strong> et <strong>EEG</strong> : si une étiologie neurologique est suspectée (traumatisme, AVC, épilepsie...).</li><li><strong>Ponction lombaire</strong> : si une infection du système nerveux central est suspectée (méningite, encéphalite...).</li><li><strong>Examen CytoBactériologique des Urines (ECBU)</strong> : pour rechercher une infection urinaire, source fréquente d'agitation chez le sujet âgé notamment.</li></ul>"},{"i":"c0bc0d31007c","n":351,"o":"351-10","u":"Prise en charge","t":"Connaître les indications et la mise en œuvre des examens complémentaires dans un contexte d’agitation","q":"Quel examen cardiologique est impératif avant d'administrer un traitement sédatif (notamment un antipsychotique) face à une agitation aiguë ?","a":"<p>Un <strong>électrocardiogramme (ECG)</strong> est impératif avant tout traitement sédatif, particulièrement avant un antipsychotique, afin de rechercher systématiquement un <strong>allongement de l'espace QT</strong> et prévenir le risque de troubles du rythme.</p>"},{"i":"480528fc738f","n":351,"o":"351-11","u":"Prise en charge","t":"Connaître les principes de la prise en charge de l’épisode délirant aigu, de l’état d’agitation","q":"Quels sont les risques liés à la contention physique lors de la prise en charge d'un patient agité ?","a":"<p>Les risques sont multiples :</p><ul><li>Aggravation d'un <strong>syndrome confusionnel</strong>.</li><li><strong>Traumatisme psychologique</strong>.</li><li><strong>Fausse route</strong> et encombrement bronchique.</li><li><strong>RGO</strong>, constipation, voire occlusion.</li><li><strong>Rétention aiguë d'urine</strong>.</li><li><strong>Escarres</strong>.</li><li><strong>Hypotension orthostatique</strong>.</li><li><strong>Maladie thromboembolique</strong>.</li></ul>"},{"i":"53cee4303ab3","n":351,"o":"351-11","u":"Prise en charge","t":"Connaître les principes de la prise en charge de l’épisode délirant aigu, de l’état d’agitation","q":"En quoi consiste la prise en charge non pharmacologique de l'agitation ou du délire aigu ?","a":"<p>Elle repose sur la <strong>prise en charge relationnelle</strong> en 1<sup>re</sup> intention :</p><ul><li>Établir un <strong>contact verbal</strong>, un <strong>climat de confiance</strong>, et adopter un <strong>comportement empathique</strong>. Cette approche désamorce une grande part des états d'agitation et prévient le passage à l'acte.</li><li>La <strong>contention physique</strong> est une pratique de <strong>dernier recours</strong>, justifiée uniquement en cas de <strong>danger important et imminent</strong> et après échec de la PEC relationnelle, à durée limitée.</li><li>Autres mesures : <strong>environnement calme</strong>, chambre éclairée, retrait des objets dangereux, fermeture des fenêtres.</li></ul>"},{"i":"57c5b080865e","n":351,"o":"351-11","u":"Prise en charge","t":"Connaître les principes de la prise en charge de l’épisode délirant aigu, de l’état d’agitation","q":"Quels sont les traitements pharmacologiques de première intention pour l'agitation ou le délire aigu, et leurs voies d'administration privilégiées ?","a":"<p>Les traitements sont à visée symptomatique (sédative et/ou anxiolytique) :</p><ul><li><strong>Anxiolytiques</strong> :</li><ul><li>1<sup>re</sup> intention : <strong>benzodiazépine à demi-vie courte par voie orale</strong> (ex: <strong>oxazépam</strong>) ou autre anxiolytique (ex: <strong>hydroxyzine</strong>).</li><li>Si voie orale impossible : anxiolytique <strong>intramusculaire autre qu'une BZD</strong>.</li></ul><li><strong>Antipsychotiques à visée sédative</strong> (en deuxième intention ou si refus de PO avec mise en danger) :</li><ul><li>Par voie orale : <strong>cyamémazine</strong>, <strong>lévomépromazine</strong>, <strong>loxapine</strong>.</li><li>En cas de refus avec mise en danger : <strong>halopéridol</strong> ou <strong>loxapine IM</strong>.</li></ul></ul>"},{"i":"5b9e690d9dd6","n":351,"o":"351-11","u":"Prise en charge","t":"Connaître les principes de la prise en charge de l’épisode délirant aigu, de l’état d’agitation","q":"Quels sont les principes généraux du traitement pharmacologique de l'agitation ou du délire aigu ?","a":"<p>Les principes sont :</p><ul><li>Privilégier la <strong>monothérapie</strong>.</li><li>Privilégier la <strong>voie orale</strong>.</li><li>Utiliser les <strong>doses d'anxiolytiques les plus faibles</strong> possible (surtout chez le sujet âgé).</li><li>Éviter l'<strong>escalade des doses</strong> (effets cumulatifs différés sur la vigilance).</li><li>Réaliser une <strong>surveillance rapprochée</strong> (tolérance, efficacité).</li></ul>"},{"i":"8539b2b5e027","n":351,"o":"351-11","u":"Prise en charge","t":"Connaître les principes de la prise en charge de l’épisode délirant aigu, de l’état d’agitation","q":"Quelles sont les contre-indications à l'utilisation des benzodiazépines et quelles précautions prendre avant l'administration d'antipsychotiques sédatifs ?","a":"<p>Les contre-indications aux benzodiazépines sont l'<strong>insuffisance respiratoire</strong> et la <strong>myasthénie</strong>.</p><p>Avant l'administration d'antipsychotiques sédatifs, un <strong>ECG préalable</strong> est recommandé pour rechercher un <strong>QT long</strong> (la cyamémazine IM est non recommandée dans ce cas).</p>"},{"i":"d71d89c30788","n":351,"o":"351-11","u":"Prise en charge","t":"Connaître les principes de la prise en charge de l’épisode délirant aigu, de l’état d’agitation","q":"Quelle est la première mesure à prendre dans la prise en charge d'un épisode délirant aigu ou d'un état d'agitation, et quels sont les principes d'hospitalisation ?","a":"<p>La première mesure est le <strong>traitement étiologique</strong>. L'hospitalisation en psychiatrie est indiquée en urgence :</p><ul><li>Par défaut, elle se fait <strong>avec consentement</strong>.</li><li>En cas de refus du patient et de mise en danger, elle se fait <strong>sans consentement</strong>.</li></ul>"},{"i":"0ad77bcac47e","n":351,"o":"351-12","u":"Prise en charge","t":"Connaître les indications et les modalités de l’hospitalisation libre et sans consentement selon l’âge","q":"Dans quel contexte sont indiqués les Soins Psychiatriques Sans Consentement (SPSC) pour la prise en charge de l'agitation et du délire aigu ?","a":"<p>Les Soins Psychiatriques Sans Consentement (SPSC) sont indiqués pour la prise en charge de l'agitation et du délire aigu dans les situations où les <strong>troubles mentaux du patient rendent son consentement impossible et nécessitent des soins immédiats</strong>.</p>"},{"i":"8d914e291edb","n":351,"o":"351-12","u":"Prise en charge","t":"Connaître les indications et les modalités de l’hospitalisation libre et sans consentement selon l’âge","q":"Quelles sont les spécificités des Soins Psychiatriques en cas de Péril Imminent (SPPI) et des Soins sur Décision du Représentant de l'État (SPDRE) ?","a":"<p>Les spécificités sont :</p><ul><li><strong>Soins en cas de Péril Imminent (SPPI)</strong> : Cette modalité sans tiers permet une admission au vu d'<strong>un seul certificat médical</strong> constatant un <strong>péril imminent pour la santé du patient</strong>, prononcée par le directeur de l'établissement.</li><li><strong>Soins sur Décision du Représentant de l'État (SPDRE)</strong> : Cette modalité est activée lorsque les troubles nécessitent des soins et <strong>compromettent la sûreté des personnes ou portent gravement atteinte à l'ordre public</strong>. La procédure implique un <strong>arrêté du préfet</strong> et un <strong>certificat médical</strong> (hors médecin de l'établissement d'accueil).</li></ul>"},{"i":"f5d02d739814","n":351,"o":"351-12","u":"Prise en charge","t":"Connaître les indications et les modalités de l’hospitalisation libre et sans consentement selon l’âge","q":"Quelles sont les conditions et la procédure pour une hospitalisation sous Soins Psychiatriques à la Demande d'un Tiers (SPDT) ?","a":"<p>Les conditions pour une SPDT sont :</p><ul><li>Un <strong>état mental nécessitant des soins immédiats et une surveillance constante</strong>.</li><li>Des <strong>troubles rendant le consentement impossible</strong>.</li></ul><p>La procédure implique :</p><ul><li>Une <strong>demande manuscrite d'un tiers</strong> (famille ou proche, hors soignants de l'établissement).</li><li><strong>Deux certificats médicaux circonstanciés de moins de 15 jours</strong>.</li><li>L'admission est prononcée par le <strong>directeur de l'établissement</strong>.</li></ul>"},{"i":"9547d0a2aa1e","n":351,"o":"351-2","u":"Définition","t":"Connaître la définition des idées délirantes et hallucinations","q":"Quelle est la définition d'une hallucination dans le cadre de l'agitation et du délire aigu ?","a":"<p>Une hallucination est une <strong>perception sans objet</strong>.</p>"},{"i":"9548dc52c737","n":351,"o":"351-2","u":"Définition","t":"Connaître la définition des idées délirantes et hallucinations","q":"Quelle est l'importance des idées délirantes et hallucinations en sémiologie psychiatrique ?","a":"<p>Les idées délirantes et les hallucinations sont les <strong>deux symptômes psychotiques de référence</strong>.</p>"},{"i":"9bba76297547","n":351,"o":"351-2","u":"Définition","t":"Connaître la définition des idées délirantes et hallucinations","q":"Quelle est la définition d'une idée délirante dans le cadre de l'agitation et du délire aigu ?","a":"<p>Une idée délirante est une <strong>croyance erronée fondée sur une déduction incorrecte concernant la réalité</strong>, fermement soutenue en dépit de l'opinion générale et de toute preuve incontestable et évidente du contraire.</p>"},{"i":"6dc17fd6545f","n":351,"o":"351-3","u":"Définition","t":"Connaître la définition du délire aigu","q":"Quelle est la relation entre le délire aigu et l'agitation ?","a":"<p>Le <strong>délire aigu</strong> et l'<strong>agitation</strong> sont deux syndromes <strong>distincts</strong> et ne sont pas systématiquement associés.</p>"},{"i":"a1a56a53c490","n":351,"o":"351-3","u":"Définition","t":"Connaître la définition du délire aigu","q":"Comment définit-on le délire aigu en psychiatrie ?","a":"<p>Le délire aigu se définit par la présence d'<strong>une ou plusieurs idées délirantes</strong> d'<strong>apparition récente</strong>, évoluant depuis <strong>moins d'un mois</strong>.</p>"},{"i":"44ebf658f8e9","n":351,"o":"351-4","u":"Etiologie","t":"Connaître les étiologies de l’agitation selon l’âge incluant les causes toxiques","q":"Quelles sont les causes toxiques les plus fréquentes d'agitation chez l'adulte jeune ?","a":"<p>Les causes toxiques fréquentes chez l'adulte jeune incluent :</p><ul><li><strong>Intoxication aiguë</strong> : alcool, cannabis et LSD (hallucinogènes), cocaïne, amphétamine, ecstasy (psychostimulants), monoxyde de carbone.</li><li><strong>Sevrage</strong> : alcool, héroïne, morphiniques.</li></ul>"},{"i":"7c702629a9bc","n":351,"o":"351-4","u":"Etiologie","t":"Connaître les étiologies de l’agitation selon l’âge incluant les causes toxiques","q":"Quelles sont les principales causes neurologiques et infectieuses d'agitation à considérer selon l'âge ?","a":"<ul><li><strong>Causes neurologiques</strong> :<ul><li>Chez le sujet âgé : <strong>AVC</strong>, crise convulsive, hématome sous-dural (HSD) / épidural (HED), tumeur, démence débutante.</li><li>Chez l'adulte jeune : <strong>crise convulsive</strong>, AVC.</li></ul></li><li><strong>Causes infectieuses</strong> :<ul><li>Chez le sujet âgé : infections courantes (<strong>urinaire, pulmonaire</strong> notamment).</li><li>Chez l'adulte jeune : <strong>méningo-encéphalite herpétique</strong>, neuropaludisme.</li></ul></li></ul>"},{"i":"8bd6d273caf4","n":351,"o":"351-4","u":"Etiologie","t":"Connaître les étiologies de l’agitation selon l’âge incluant les causes toxiques","q":"Quelles sont les principales causes iatrogènes d'agitation chez le sujet âgé, comme cité dans le contenu ?","a":"<ul><li>Les <strong>benzodiazépines (BZD)</strong> : peuvent provoquer un syndrome confusionnel à l'instauration ou au sevrage, ou un effet paradoxal.</li><li>Les <strong>antidépresseurs</strong> : confusion, syndrome sérotoninergique, ou virage maniaque/hypomaniaque.</li><li>Autres : <strong>corticoïdes</strong>, <strong>agonistes dopaminergiques</strong>, <strong>anticholinergiques</strong>, et plus rarement antipaludéens, isoniazide, interféron.</li></ul>"},{"i":"cc60526468e3","n":351,"o":"351-4","u":"Etiologie","t":"Connaître les étiologies de l’agitation selon l’âge incluant les causes toxiques","q":"Quelle est la première étape systématique face à une agitation chez un patient, quel que soit son âge ou ses antécédents, et pourquoi est-elle cruciale ?","a":"<p>La première étape est toujours d'<strong>éliminer une cause non psychiatrique</strong>. Cette démarche est cruciale car de nombreuses pathologies somatiques, intoxications ou effets indésirables médicamenteux peuvent se manifester par une agitation, et nécessitent une prise en charge spécifique et rapide.</p>"},{"i":"dcffe1e0e066","n":351,"o":"351-4","u":"Etiologie","t":"Connaître les étiologies de l’agitation selon l’âge incluant les causes toxiques","q":"Quelles étiologies métaboliques ou endocriniennes peuvent être à l'origine d'une agitation chez le sujet âgé ou l'adulte jeune ?","a":"<p>Les étiologies métaboliques ou endocriniennes comprennent :</p><ul><li><strong>Chez le sujet âgé</strong> : dysnatrémie, hypercalcémie, hyperthyroïdie, hypoglycémie.</li><li><strong>Chez l'adulte jeune</strong> : hypoglycémie, hyperthyroïdie, dysnatrémie, hypercalcémie.</li></ul><p>Ces causes sont communes aux deux tranches d'âge principales.</p>"},{"i":"171fdad12320","n":351,"o":"351-5","u":"Etiologie","t":"Connaître les étiologies des syndromes délirants aigus selon l’âge incluant les causes toxiques","q":"Quelles sont les principales étiologies non psychiatriques d'un syndrome délirant aigu devant être recherchées en priorité chez l'adulte jeune ?","a":"<p>Chez l'adulte jeune, les étiologies non psychiatriques à rechercher en priorité devant un syndrome délirant aigu sont :</p><ul><li>Les causes <strong>iatrogènes</strong>.</li><li>Les causes <strong>infectieuses</strong>.</li><li>Les causes <strong>métaboliques</strong>.</li><li>Les causes <strong>endocriniennes</strong>.</li></ul>"},{"i":"5c2b3310aa11","n":351,"o":"351-5","u":"Etiologie","t":"Connaître les étiologies des syndromes délirants aigus selon l’âge incluant les causes toxiques","q":"Quelles sont les principales étiologies non psychiatriques d'un syndrome délirant aigu devant être recherchées en priorité chez le sujet âgé ?","a":"<p>Chez le sujet âgé, les étiologies non psychiatriques à rechercher en priorité devant un syndrome délirant aigu sont :</p><ul><li>Les causes <strong>iatrogènes</strong>.</li><li>Les causes <strong>métaboliques</strong>.</li><li>Les causes <strong>neurologiques</strong>.</li><li>Les causes <strong>infectieuses</strong>.</li><li>Les causes <strong>toxiques</strong>.</li></ul>"},{"i":"ad128721bb14","n":351,"o":"351-5","u":"Etiologie","t":"Connaître les étiologies des syndromes délirants aigus selon l’âge incluant les causes toxiques","q":"Quelles sont les étiologies psychiatriques à évoquer devant un syndrome délirant aigu avec des symptômes thymiques associés, et quelles sont leurs caractéristiques délirantes ?","a":"<p>En cas de symptômes thymiques associés, les étiologies psychiatriques à évoquer sont :</p><ul><li>Un <strong>épisode maniaque ou mixte</strong> : le délire est souvent à thème <strong>mégalomaniaque ou de persécution</strong>, avec accélération psychomotrice, logorrhée et diminution du besoin de sommeil, dans un contexte de trouble bipolaire ou de virage de l'humeur sous antidépresseur.</li><li>Un <strong>épisode dépressif caractérisé</strong> : le délire est à thèmes de <strong>culpabilité, d'hypochondrie ou de ruine</strong>, associé à un ralentissement psychomoteur.</li></ul>"},{"i":"fa6f77a98ddd","n":351,"o":"351-5","u":"Etiologie","t":"Connaître les étiologies des syndromes délirants aigus selon l’âge incluant les causes toxiques","q":"Quelles sont les étiologies psychiatriques à évoquer devant un syndrome délirant aigu avec des symptômes psychotiques sans prédominance thymique marquée ?","a":"<p>En présence d'autres symptômes psychotiques sans prédominance thymique marquée, les étiologies psychiatriques à évoquer sont :</p><ul><li>Un <strong>trouble psychotique bref</strong> : idées délirantes, hallucinations et désorganisation d'une durée <strong>supérieure à 1 jour et inférieure à 1 mois</strong>.</li><li>Un <strong>trouble psychotique chronique débutant ou non diagnostiqué</strong> :<ul><li>Durée <strong>inférieure à 6 mois</strong> : <strong>trouble schizophréniforme</strong>.</li><li>Durée <strong>supérieure à 6 mois</strong> : <strong>schizophrénie</strong> ou <strong>trouble schizoaffectif</strong>.</li><li>Durée <strong>supérieure à 1 mois</strong> (pour le délire isolé) : <strong>trouble délirant</strong>.</li></ul></li><li>Des <strong>troubles psychotiques du post-partum</strong>.</li></ul>"},{"i":"12087b35d1a5","n":351,"o":"351-6","u":"Diagnostic positif","t":"Savoir diagnostiquer une agitation","q":"Comment pose-t-on le diagnostic d'agitation en médecine ?","a":"<p>Le diagnostic d'agitation est <strong>clinique</strong> et repose sur sa définition : une <strong>activité motrice excessive improductive</strong> associée à un <strong>état de tension intérieure</strong>.</p>"},{"i":"54a7e25d09b3","n":351,"o":"351-6","u":"Diagnostic positif","t":"Savoir diagnostiquer une agitation","q":"Pourquoi l'interrogatoire de l'entourage est-il essentiel lors de la prise en charge d'un patient agité ?","a":"<p>L'interrogatoire de l'entourage est central (<strong>+++</strong>) car le patient agité est souvent non coopérant et ne peut pas fournir un historique fiable ou pertinent.</p>"},{"i":"65c3df94fa2d","n":351,"o":"351-6","u":"Diagnostic positif","t":"Savoir diagnostiquer une agitation","q":"Quels sont les éléments clés à recueillir lors de l'interrogatoire pour diagnostiquer une agitation ?","a":"<ul><li>La <strong>date de début</strong> et le <strong>mode évolutif</strong> (brutal vs progressif, permanent vs intermittent).</li><li>Les <strong>facteurs déclenchants</strong> éventuels.</li><li>La <strong>prise de toxiques</strong> (alcool, drogues, médicaments).</li><li>Les <strong>antécédents détaillés +++</strong>, afin de rechercher une décompensation aiguë d'une pathologie sous-jacente.</li></ul>"},{"i":"88e7eaf8a738","n":351,"o":"351-6","u":"Diagnostic positif","t":"Savoir diagnostiquer une agitation","q":"Quels sont les principaux diagnostics différentiels à écarter face à une agitation ?","a":"<p>Les principaux diagnostics différentiels sont :</p><ul><li>L'<strong>hyperactivité physique</strong> : se différencie par une motricité orientée vers un but et généralement productive.</li><li>L'<strong>akathisie</strong> : un besoin irrépressible de bouger, souvent ressenti comme une anxiété interne, mais sans l'aspect désorganisé et la tension.</li></ul>"},{"i":"10d65241b83c","n":351,"o":"351-7","u":"Diagnostic positif","t":"Connaître l’analyse sémiologique d’un syndrome délirant","q":"Quels sont les différents mécanismes par lesquels une idée délirante peut s'établir ?","a":"<p>Les mécanismes d'établissement d'une idée délirante incluent :</p><ul><li><strong>Interprétatif</strong> : interprétation délirante d'un fait réel.</li><li><strong>Hallucinatoire</strong> : perception sans objet.</li><li><strong>Intuitif</strong> : conviction délirante d'emblée.</li><li><strong>Imaginatif</strong> : fabulation ou invention.</li></ul>"},{"i":"77c1c71a4fc9","n":351,"o":"351-7","u":"Diagnostic positif","t":"Connaître l’analyse sémiologique d’un syndrome délirant","q":"Comment évalue-t-on l'adhésion du patient à son délire et son retentissement ?","a":"<ul><li>L'<strong>adhésion</strong> est évaluée par le degré de conviction : elle peut être <strong>totale</strong> (inébranlable, inaccessible au raisonnement) ou <strong>partielle</strong> (le patient a une capacité d'autocritique).</li><li>Le <strong>retentissement</strong> est évalué par ses conséquences émotionnelles (niveau d'anxiété souvent majeur) et comportementales, en recherchant systématiquement un <strong>risque suicidaire</strong> et un <strong>risque hétéro-agressif</strong>.</li></ul>"},{"i":"c3f235075c3a","n":351,"o":"351-7","u":"Diagnostic positif","t":"Connaître l’analyse sémiologique d’un syndrome délirant","q":"Quels sont les 5 axes sémiologiques à caractériser systématiquement pour analyser une idée délirante ?","a":"<p>Les 5 axes sémiologiques indispensables pour analyser une idée délirante sont :</p><ul><li>Le <strong>thème</strong></li><li>Le <strong>mécanisme</strong></li><li>La <strong>systématisation</strong></li><li>L'<strong>adhésion</strong></li><li>Le <strong>retentissement</strong> (émotionnel et comportemental)</li></ul>"},{"i":"f0ed2726d741","n":351,"o":"351-7","u":"Diagnostic positif","t":"Connaître l’analyse sémiologique d’un syndrome délirant","q":"Quelle est la différence entre une idée délirante systématisée et non systématisée ?","a":"<ul><li>Une idée délirante <strong>systématisée</strong> (ou paranoïaque) présente un <strong>thème unique</strong> et une organisation interne <strong>logique</strong>.</li><li>Une idée délirante <strong>non systématisée</strong> (ou paranoïde) présente des <strong>thèmes multiples</strong> et une organisation interne <strong>incohérente</strong>, sans logique.</li></ul>"},{"i":"0cca7bfd5ae1","n":351,"o":"351-8","u":"Diagnostic positif","t":"Connaître l’analyse sémiologique d’un syndrome hallucinatoire","q":"Quels phénomènes traduisent une perte de l'intimité psychique dans le cadre des hallucinations intrapsychiques ?","a":"<p>Ces phénomènes s'intègrent dans l'<strong>automatisme mental</strong> et incluent :</p><ul><li>Le <strong>vol de la pensée</strong>.</li><li>La divulgation ou le <strong>devinement de la pensée</strong>.</li><li>La <strong>transmission de la pensée</strong>.</li><li>Les <strong>pensées imposées</strong> : le sujet entend ses pensées comme si elles venaient d'autrui.</li><li>L'<strong>écho de la pensée</strong> : le sujet entend ses propres pensées répétées à voix haute, comme renvoyées par un écho.</li></ul>"},{"i":"597f5e314ba8","n":351,"o":"351-8","u":"Diagnostic positif","t":"Connaître l’analyse sémiologique d’un syndrome hallucinatoire","q":"Quelles sont les caractéristiques sémiologiques des hallucinations auditives, et quels signes cliniques peuvent évoquer leur présence ?","a":"<p>Les hallucinations auditives sont les plus fréquentes. Elles peuvent être des sons simples (sonnerie) ou, plus souvent, des <strong>hallucinations acoustico-verbales (HAV)</strong> :</p><ul><li>Voix nettement <strong>localisées dans l'espace</strong>.</li><li>Conversant entre elles ou s'adressant au sujet à la <strong>3ᵉ personne</strong>.</li><li>Phrases courtes à connotation <strong>négative</strong>.</li></ul><p>Les signes cliniques évocateurs sont :</p><ul><li><strong>Attitudes d'écoute</strong>.</li><li>Moyens de protection (musique, se boucher les oreilles).</li><li>Réponses brèves ou en aparté.</li><li><strong>Soliloquie</strong> (parler tout seul).</li><li>Distractibilité pendant l'entretien.</li></ul>"},{"i":"6e435f014101","n":351,"o":"351-8","u":"Diagnostic positif","t":"Connaître l’analyse sémiologique d’un syndrome hallucinatoire","q":"Décrivez les caractéristiques sémiologiques des hallucinations visuelles, tactiles, cénesthésiques, olfactives et gustatives.","a":"<ul><li><strong>Visuelles</strong> : elles peuvent être élémentaires (lumières, taches colorées, phosphènes, ombres, flashs) ou complexes (objets, figures, scènes).</li><li><strong>Tactiles</strong> : sensations de coups de vent, brûlures, piqûres, ou d'être couvert de parasites. Le patient peut parfois \"toucher\" ses hallucinations.</li><li><strong>Cénesthésiques</strong> : elles intéressent la sensibilité interne avec des impressions de transformation du corps (évidement, éclatement, possession).</li><li><strong>Olfactives / Gustatives</strong> (moins fréquentes) : Les olfactives sont le plus souvent de <strong>mauvaises odeurs</strong> émanant du patient lui-même. Les gustatives sont une modification du goût des aliments.</li></ul>"},{"i":"920902f7ae69","n":351,"o":"351-8","u":"Diagnostic positif","t":"Connaître l’analyse sémiologique d’un syndrome hallucinatoire","q":"Quels sont les deux grands types d'hallucinations en sémiologie psychiatrique et leurs caractéristiques principales ?","a":"<ul><li>Les <strong>hallucinations psychosensorielles</strong> : il s'agit de perceptions sans objet qui relèvent d'une manifestation sensorielle, via l'un des <strong>5 sens</strong>. Elles peuvent toucher l'audition, la vision, le toucher, le goût ou l'olfaction. Elles sont perçues comme extérieures au sujet.</li><li>Les <strong>hallucinations intrapsychiques</strong> : ce sont des phénomènes psychiques vécus dans la propre pensée du patient, sans manifestation sensorielle ni spatialité. Elles sont perçues comme <strong>étrangères</strong> au sujet et traduisent une perte de l'intimité psychique (ex: vol de la pensée, pensées imposées).</li></ul>"},{"i":"eafda8d72533","n":351,"o":"351-8","u":"Diagnostic positif","t":"Connaître l’analyse sémiologique d’un syndrome hallucinatoire","q":"Quelle est la définition d'une hallucination en sémiologie psychiatrique ?","a":"<p>Une hallucination est une <strong>perception sans objet</strong>, c'est-à-dire une perception qui ne correspond à aucun stimulus externe réel.</p>"}]};